import * as THREE from 'three';
let texture;
function contactMap122(){if(texture)return texture;const size=64,data=new Uint8Array(size*size*4);for(let y=0;y<size;y++)for(let x=0;x<size;x++){const a=(x+.5)/size*2-1,b=(y+.5)/size*2-1,r=a*a+b*b;data[(y*size+x)*4+3]=Math.round(Math.max(0,Math.exp(-r*4.8)-Math.exp(-4.8))*255);}texture=new THREE.DataTexture(data,size,size);texture.magFilter=THREE.LinearFilter;texture.minFilter=THREE.LinearMipmapLinearFilter;texture.generateMipmaps=true;texture.userData.quality100Shared=true;texture.needsUpdate=true;return texture;}
function contactBatch122(capacity,opacity){const g=new THREE.PlaneGeometry(1,1);g.rotateX(-Math.PI/2);const m=new THREE.MeshBasicMaterial({color:0x10181a,map:contactMap122(),transparent:true,opacity,depthWrite:false,polygonOffset:true,polygonOffsetFactor:-1});const mesh=new THREE.InstancedMesh(g,m,capacity);mesh.name='Contacto_suelo122';mesh.frustumCulled=false;mesh.count=0;mesh.raycast=()=>{};mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);return mesh;}
export class PassengerContacts122{
 constructor(scene,capacity=1160){this.mesh=contactBatch122(capacity*2,.34);scene.add(this.mesh);this.matrix=new THREE.Matrix4();this.p=new THREE.Vector3();this.q=new THREE.Quaternion();this.s=new THREE.Vector3();this.axis=new THREE.Vector3(0,1,0);}
 update(actors,time,route){let n=0;for(const a of actors){const yaw=a.yaw||0,child=a.modelType==='child'?.72:1,seated=a.pose==='seated';for(const side of[-1,1]){const x=side*.105*child,phase=time*Math.PI*2,stride=a.moving?Math.sin(phase)*side*.16:0,z=(seated?.36:stride)*child;const px=a.x+x*Math.cos(yaw)+z*Math.sin(yaw),pz=a.z-x*Math.sin(yaw)+z*Math.cos(yaw),pose=route?.pose(px,pz);this.p.set(pose?.x??px,a.y+.012,pose?.z??pz);this.q.setFromAxisAngle(this.axis,yaw+(pose?.yaw||0));this.s.set(.30*child,1,.44*child);this.matrix.compose(this.p,this.q,this.s);if(n<this.mesh.instanceMatrix.count)this.mesh.setMatrixAt(n++,this.matrix);}}
 this.mesh.count=n;this.mesh.visible=n>0;this.mesh.instanceMatrix.needsUpdate=n>0;return n;}
}
export function stationContacts122(source){source.updateMatrixWorld(true);const slots=[],box=new THREE.Box3(),size=new THREE.Vector3(),center=new THREE.Vector3();source.traverse(o=>{if(!o.isMesh||!(o.userData.componente==='estructura'||/^Columna|^Pilar/i.test(o.name)))return;box.setFromObject(o);box.getSize(size);box.getCenter(center);if(size.y<1.7&&!/basamento|base.*pilar/i.test(o.name)||size.x>2.5||size.z>2.5||Math.abs(box.min.y-1.2)>.22)return;slots.push({x:center.x,y:box.min.y+.012,z:center.z,w:Math.max(.25,size.x*1.9),d:Math.max(.25,size.z*1.9)});});
 const group=new THREE.Group();group.name='Apoyo_columnas122';if(!slots.length)return group;
 const mesh=contactBatch122(slots.length,.25),matrix=new THREE.Matrix4(),q=new THREE.Quaternion();for(let i=0;i<slots.length;i++){const a=slots[i];matrix.compose(new THREE.Vector3(a.x,a.y,a.z),q,new THREE.Vector3(a.w,1,a.d));mesh.setMatrixAt(i,matrix);}mesh.count=slots.length;mesh.userData.componente='contacto_columnas';group.add(mesh);return group;}
